import{_ as a,o as t,c as e,a3 as _}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/88-去激活策略也有好处.md","filePath":"books/attached/88-去激活策略也有好处.md","lastUpdated":1794298621000}'),o={name:"books/attached/88-去激活策略也有好处.md"};function r(s,p,d,n,c,i){return t(),e("div",null,[...p[0]||(p[0]=[_('<h3 id="去激活策略也有好处" tabindex="-1">去激活策略也有好处 <a class="header-anchor" href="#去激活策略也有好处" aria-label="Permalink to &quot;去激活策略也有好处&quot;">​</a></h3><p>其实在玛莎分手之前很久，她就在下意识地压抑自己的依恋机制，准备逃离这段关系了。她花了好几年时间尝试着改变格雷格，包括阐释自己的观点；情绪上的爆发；建议他改掉一些习惯等等，但最终还是放弃了。在访谈中，玛莎告诉我们，他们在一起的初期，自己还常常以泪洗面，到最后的日子，自己已经很少哭了。也就是说，在感性层面，她已经做好了分开的准备。她再也不寄希望于克雷格，或者他们的关系能有什么转机。她的关注点越来越多地放在克雷格的缺点上，而不再对两人的美好时光念念不忘。她后来的行为就有点像回避型依恋风格的一贯表现了：开始避免两人过于亲密；开始关注对方的缺点；开始产生折磨对方的行为。玛莎即使作为一个焦虑型的人，在遭到克雷格无限的伤害之后，也开始产生了去激活策略。在希望将一个人剔除出你的依恋机制之外时，去激活策略是一种必要的手段。这个过程也需要伴侣的配合，不过千万别太自信，笃定自己不会经历反弹效应。一旦你的依恋机制又因为分手而重新激活，一切就都功亏一篑了。在玛莎的案例中，产生去激活策略的过程帮助她相对顺利地提出了分手以及最终的离婚。</p><p>现在，玛莎已经不再和克雷格联系，他们也不再是朋友关系。她也随即找到了自己真正的灵魂伴侣。</p><p>走出分手阴霾</p><p>下面是基于依恋原则的九条策略，或许能够帮助你度过亲密关系结束之后，最痛苦的一段时光。</p><p>1.自我确定亲密关系的性质。</p><p>在你没办法下定决心分手的时候，问问自己，对方到底待你如掌上明珠还是敌人。如果你的答案是敌人，那就是时候离开了。</p><p>2.预先建立社会支持网络。</p><p>一定要将亲密关系的真实情况坦白给周围的家人和朋友。一来有利于使从前一直忽视，长久以来都不好意思敞开心扉的友谊重新升温，同时也有利于在分手以后获得他们的帮助。（具体做法见第7条。）</p><p>3.分手后的几天，找个舒适而能为你提供支持的地方待着。</p><p>分手伊始，你需要动用所有可能获得的支持。因为反弹效应在此时非常强烈，而父母、兄弟姐妹以及密友，都能帮助你控制回头的冲动。</p><p>4.通过其他的方式来获取依恋需求。</p><p>可以从其他亲密的人那儿获取支持，还可以通过线上聊天、大量的运动、按摩、烹食健康的食物来转移注意。你越是成功地将依恋机制安抚下去，分手的伤痛就越小。</p><p>5.分手之后不要感到愧疚，也不要因此而“故地重游”。</p><p>你最好不要跟前任重新联系，但要是没忍住，也不要过于困惑。这个阶段一定要对自己宽容一点，因为越是对自己感觉糟糕，你就会越想回到那段糟糕的关系，寻求错误的安全感。在你苛责自己的时候，依恋机制很容易被激活，这时候你会更渴望与对方产生联系。</p><p>6.如果你感觉到很难走出来，千万不要有负罪感，要知道这些痛苦是必经的！</p><p>你的朋友可能会催着你忘记前任，让你别再折磨自己，快些走出来。但你清楚地知道，这些痛苦是切实存在的，所以应该坦然接受它们。对自己好一点，追求身心的放松，毕竟腿断了也需要养一阵子啊！</p><p>7.当与前任的美好回忆涌起，记得找一个密友来给你客观的评价。</p><p>要时刻提醒自己，你的依恋机制会扰乱自己对于亲密关系的评价。要找一位朋友时刻提醒你事情的真实一面。如此一来，即使你偶尔思念或者美化前任，在时刻提醒之下，中肯的事实也会逐渐令你印象深刻。</p><p>8.去激活策略：写下所有促使你分手的原因。</p><p>你的首要目标就是压抑自己的依恋机制，而最有效的方式就是不断唤起这段关系的糟糕记忆。而让这些记忆保持鲜活的方法，就是把它们都列出来。当美好回忆入侵自己脑海的时候，就瞥一眼这条清单，将不客观的念头打消掉。</p><p>9.要知道不管经历了多少困难，他们都会过去的。</p><p>大多数人都可以从心碎中恢复过来，并且重新找到更加优秀的伴侣！</p>',23)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
